#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
uniform shader amzt_xcipher;
float4 amzSample_xcipher(float2 uv) { return float4(amzt_xcipher.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_xcipher(uv);return float4(0.0); }
uniform float amzp_AMOUNT;
uniform float amzp_ITER;
uniform float amzp_xxa;
uniform float amzp_xxp;
uniform float amzp_xxq;
uniform float amzp_xxr;
uniform float amzp_xxs;
uniform float amzp_xxe;
uniform float amzp_xxf;
uniform float amzp_xxg;
uniform float amzp_xxm;
uniform float amzp_scale;
uniform float amzp_angle;
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
layout(color) uniform half4 amzp_color3;
layout(color) uniform half4 amzp_color4;
layout(color) uniform half4 amzp_color5;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_hardness;
    float4 newLayer( float4 a, float4 b) { return a * (1. - b.a) + b; }
    float2x2 rot2m(float a){ float s = sin(a); float c = cos(a); return float2x2(c, -s, s, c); }
    float2 l2s( float2 v ) { return (float4(v,0.0,1.0)*amzLayerToScreen()).xy; }
        float2x2 rot(float a)
        {
            float c = cos(a);
            float s = sin(a);
            return float2x2(c, s, -s, c);
        }
        float field(float3 p)
        {
            p.x -= 2.0;
            p.y += sin(p.z*0.2+amzp_xxa)*2.;
            p.y += cos(p.x*0.2-amzp_xxa)*2.;
            p.z += amzp_xxa;
            p.xz = mod(p.xz+float2(2.0), 4.0)-float2(2.0);
            float3 bp = abs(p) - 1.;
            return min(max(max(bp.x, bp.y), bp.z), p.y+.9);
        }
        float march(float3 ro, float3 rd)
        {
            float t = 0.0;
            for(int i=0; i<int(amzp_AMOUNT); ++i) {
             float d = field(ro+rd*t);
                if(d < 0.0001 || d > 200.0) break;
                t += d*1.0;
            }
            return t;
        }
        float3 getNormal(float3 p)
        {
            float2 eps = float2(amzp_xxe*pow(length(p), amzp_xxf), amzp_xxg);
            return normalize(float3(
             field(p+eps.xyy) - field(p-eps.xyy),
                field(p+eps.yxy) - field(p-eps.yxy),
                field(p+eps.yyx) - field(p-eps.yyx)
            ));
        }
        float getSss(float3 ro, float3 rd)
        {
            float t = 0.0;
            for(float i=0.0; i<amzp_ITER; i+= 0.1) {
             t += field(ro+rd*i);
            }
            return clamp(exp(t*0.1), 0.0, amzp_xxm);
        }
        float getAo(float3 ro, float3 rd)
        {
            float t = 0.0;
            ro += rd*0.002;
            int i;
            for(i=0; i<64; ++i) {
             float d = field(ro+rd*t);
                if(d < 0.001 || d > 100.0) break;
                t += d;
            }
            return float(i);
        }
        void amzRender() {
        float4 texColor = amzTexture(0,amzScreenNorm());
        float4 texColorX = float4(0.0,0.0,0.0,1.0) * texColor.a;
        float2 image_size = getTexSize((screen.zw/1.0));
        float2 iResolution = float2(screen.zw.x, screen.zw.y);
        float2 iMouse = float2(0.5, 0.5);
        float2 satriyaid;
        satriyaid = ((float2(amzScreenNorm().x,1.0-amzScreenNorm().y)*screen.zw)-amzLayerCenter())/layer;
        satriyaid.y*=layer.y/layer.x;
        satriyaid /= amzp_scale;
        satriyaid *= rot2m((-180.0+amzp_angle)*0.0174533);
        satriyaid += float2((0.0+amzp_position.x), (0.0+amzp_position.y))*float2(-1.0,1.0)/500.;
        float2 scaleVec;
        scaleVec = float2(amzp_scale*amzp_stretch.x,amzp_scale*amzp_stretch.y);
        satriyaid /= scaleVec;
     float4 fragColor;
            float2 uv = satriyaid;
            float3 cam = float3(amzp_xxp, amzp_xxq, amzp_xxr);
            float3 dir = normalize(float3(uv, -1));
            dir.yz *= rot(amzp_xxs);
            cam.z -= amzp_xxa*5.0;
            dir.xz *= rot(amzp_xxa*0.1);
            float d = march(cam, dir);
            float3 col = float3(0.0);
            if(abs(uv.y) < 0.85) {
                col = float3(amzp_color1.rgb) * uv.y+0.25;
                if(d < 100.0) {
                    float3 p = cam+dir*d;
                    float3 normal = getNormal(p);
                    col += float3(amzp_color2.rgb) * (pow(1.0-max(0.0, dot(normal, -dir)), 0.6));
                    col = float3(1.0)-pow(col, float3(0.1));
                    float ss = getSss(p, dir);
                    col += 0.2*float3(pow(ss, 0.5));
                    float ao = getAo(p, normal);
                    col *= float3(1.0-ao/428.0);
                    col += 0.5*float3(amzp_color3.rgb) * (pow(max(0.0, dot(normal, normalize(float3(-2.0, 2.0, 2.0)))), 2.0));
                    col += 0.5*float3(amzp_color4.rgb) * (pow(max(0.0, dot(normal, normalize(float3(-2.0, 2.0, -2.0)))), 2.0));
                    col = mix(col, float3(amzp_color5.rgb), d/100.0);
                }
                col = pow(col, float3(2));
            }
            col *= 1.0-length(uv)*0.4;
            fragColor = float4(pow(col, float3(1.0/2.2)),1.0);
     float4 factor = mix(texColorX,fragColor,1.0);
     amzOutput = mix(texColor, factor, amzp_alpha) * texColor.a;
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
